-- C-04: employees and their organizational assignments.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema employee_master_private;
revoke all on schema employee_master_private from public,anon,authenticated,service_role;
grant usage on schema employee_master_private to authenticated;
create function employee_master_private.allowed(a text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform entity_master_private.identity();
 if a='view'then return asset_posting_private.allowed('entities:employees','view');end if;
 return exists(select 1 from public.role_access_matrix m where m.role_id=public.app_active_role_id()and m.resource_key='entities:employees'and case a when'create'then m.can_create when'edit'then m.can_edit when'delete'then m.can_delete else false end);
exception when insufficient_privilege then return false;end$$;
create function employee_master_private.access(a text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=entity_master_private.identity();begin if not employee_master_private.allowed(a)then raise exception using errcode='42501',message='Requiere permiso explícito de mantenimiento de empleados.';end if;return sid;end$$;
create function employee_master_private.visible(sid bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return sid=entity_master_private.identity()and employee_master_private.allowed('view');exception when insufficient_privilege then return false;end$$;
create function employee_master_private.approver(id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select exists(select 1 from public.subsidiaries where project_approver='employee:'||id or administrative_approver='employee:'||id)$$;
create function employee_master_private.used(id bigint)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select employee_master_private.approver(id)or entity_master_private.used('employees',id)$$;
create function employee_master_private.dto(e public.employees)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select to_jsonb(e)||jsonb_build_object('_revision',md5(to_jsonb(e)::text),'_actions',jsonb_build_object('canEdit',employee_master_private.allowed('edit'),'canDelete',employee_master_private.allowed('delete')and not employee_master_private.used(e.employee_id)))$$;
create function employee_master_private.list()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=employee_master_private.access('view');begin return coalesce((select jsonb_agg(employee_master_private.dto(e)order by e.employee_id)from public.employees e where e.subsidiary_id=sid),'[]');end$$;
create function employee_master_private.options()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=employee_master_private.access('view');begin return jsonb_build_object('canView',true,'canCreate',employee_master_private.allowed('create'),'canEdit',employee_master_private.allowed('edit'),'canDelete',employee_master_private.allowed('delete'),'references',jsonb_build_object(
 'organization/subsidiaries',(select jsonb_agg(jsonb_build_object('subsidiary_id',s.subsidiary_id,'name',s.name))from public.subsidiaries s where s.subsidiary_id=sid),
 'organization/departments',coalesce((select jsonb_agg(jsonb_build_object('department_id',d.department_id,'name',d.name,'type',d.type))from public.departments d where d.type='Interno'and not d.is_inactive and(d.subsidiary_id=sid or exists(select 1 from public.department_subsidiaries x where x.department_id=d.department_id and x.subsidiary_id=sid))),'[]'),
 'organization/locations',coalesce((select jsonb_agg(jsonb_build_object('location_id',l.location_id,'name',l.name))from public.locations l where l.subsidiary_id=sid or exists(select 1 from public.location_subsidiaries x where x.location_id=l.location_id and x.subsidiary_id=sid)),'[]'),
 'security/users',coalesce((select jsonb_agg(jsonb_build_object('user_id',u.user_id,'first_name',u.first_name,'last_name',u.last_name,'email',u.email))from public.users u join public.user_subsidiaries us using(user_id)where us.subsidiary_id=sid and u.is_active),'[]')));end$$;
create function employee_master_private.save(p jsonb,id bigint)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=employee_master_private.access(case when id is null then'create'else'edit'end);oldrow public.employees;e public.employees;data jsonb;k text;cols text;sets text;fields text[]:=array['identification','first_name','last_name','job_title','email','phone','subsidiary_id','department_id','location_id','user_id','is_active','is_sales_representative'];begin
 if id<=0 or id>9007199254740991 or jsonb_typeof(p)is distinct from'object'or pg_column_size(p)>32000 or exists(select 1 from jsonb_object_keys(p)x where not x=any(fields||array['_revision']))then raise exception using errcode='22023',message='Campos de empleado inválidos.';end if;
 perform pg_advisory_xact_lock(793146,1);
 if id is not null then select *into oldrow from public.employees where employee_id=id for update;if not found or oldrow.subsidiary_id<>sid then raise exception using errcode='42501',message='Empleado fuera de la filial activa.';end if;if p->>'_revision'is distinct from md5(to_jsonb(oldrow)::text)then raise exception using errcode='55000',message='El empleado cambió. Consúltelo nuevamente.';end if;end if;
 data:=case when id is null then jsonb_build_object('subsidiary_id',sid,'is_active',true,'is_sales_representative',false)else to_jsonb(oldrow)end||(p-'_revision');
 foreach k in array fields loop
 if k in('is_active','is_sales_representative')then if jsonb_typeof(data->k)is distinct from'boolean'then raise exception using errcode='22023',message='Las opciones deben ser booleanas.';end if;
 elsif k in('subsidiary_id','department_id','location_id','user_id')then if data->>k=''then data:=jsonb_set(data,array[k],'null');end if;if data->>k is not null and(data->>k!~'^[1-9][0-9]{0,15}$'or(data->>k)::numeric>9007199254740991)then raise exception using errcode='22023',message='Referencia inválida.';end if;
 else if data?k and jsonb_typeof(data->k)not in('string','null')then raise exception using errcode='22023',message='Texto de empleado inválido.';end if;if data->>k is not null then data:=jsonb_set(data,array[k],coalesce(to_jsonb(nullif(btrim(data->>k),'')),'null'));end if;end if;end loop;
 e:=jsonb_populate_record(null::public.employees,data);
 if e.subsidiary_id is distinct from sid then raise exception using errcode='42501',message='El empleado pertenece a la filial activa.';end if;
 if e.identification is null or length(e.identification)>80 or e.first_name is null or length(e.first_name)>150 or e.last_name is null or length(e.last_name)>150 or length(coalesce(e.job_title,''))>250 or length(coalesce(e.phone,''))>80 then raise exception using errcode='22023',message='Revise identificación, nombre y datos de contacto.';end if;
 if e.email is not null and(length(e.email)>254 or e.email!~'^[^[:space:]@,;<>]+@[^[:space:]@,;<>]+\.[^[:space:]@,;<>]+$')then raise exception using errcode='22023',message='Correo inválido.';end if;
 if exists(select 1 from public.employees x where x.employee_id is distinct from id and lower(btrim(x.identification))=lower(e.identification))then raise exception using errcode='23505',message='Identificación no disponible.';end if;
 if e.department_id is not null and not exists(select 1 from public.departments d where d.department_id=e.department_id and d.type='Interno'and not d.is_inactive and(d.subsidiary_id=sid or exists(select 1 from public.department_subsidiaries ds where ds.department_id=d.department_id and ds.subsidiary_id=sid)))then raise exception using errcode='42501',message='Departamento interno no disponible.';end if;
 if e.location_id is not null and not exists(select 1 from public.locations l where l.location_id=e.location_id and(l.subsidiary_id=sid or exists(select 1 from public.location_subsidiaries ls where ls.location_id=l.location_id and ls.subsidiary_id=sid)))then raise exception using errcode='42501',message='Ubicación no disponible.';end if;
 if e.user_id is not null and(e.user_id is distinct from oldrow.user_id or id is null)then
 if not exists(select 1 from public.users u join public.user_subsidiaries us using(user_id)where u.user_id=e.user_id and us.subsidiary_id=sid and u.is_active)then raise exception using errcode='42501',message='Usuario activo no disponible en la filial.';end if;
 if exists(select 1 from public.employees x where x.user_id=e.user_id and x.subsidiary_id=sid and x.employee_id is distinct from id)then raise exception using errcode='23505',message='Usuario ya vinculado en esta filial.';end if;end if;
 if id is not null then
 if employee_master_private.used(id)and e.user_id is distinct from oldrow.user_id then raise exception using errcode='55000',message='El empleado tiene dependencias. No se puede cambiar el vínculo de usuario.';end if;
 if employee_master_private.approver(id)and not e.is_active then raise exception using errcode='55000',message='Reasigne el aprobador antes de desactivar al empleado.';end if;
 if oldrow.is_sales_representative and not e.is_sales_representative and exists(select 1 from public.customers where sales_representative_id=id)then raise exception using errcode='55000',message='Reasigne los clientes antes de retirar al representante.';end if;
 end if;
 select string_agg(format('%I',x),','),string_agg(format('%I=v.%I',x,x),',')into cols,sets from unnest(fields)x;
 if id is null then execute format('insert into public.employees(%s)select %s from jsonb_populate_record(null::public.employees,$1)v returning *',cols,cols)into e using to_jsonb(e);
 else execute format('update public.employees e set %s from jsonb_populate_record(null::public.employees,$1)v where e.employee_id=$2 returning e.*',sets)into e using to_jsonb(e),id;end if;
 return employee_master_private.dto(e);end$$;
create function employee_master_private.remove(id bigint,revision text)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=employee_master_private.access('delete');e public.employees;begin
 perform pg_advisory_xact_lock(793146,1);select *into e from public.employees where employee_id=id for update;if not found or e.subsidiary_id<>sid then raise exception using errcode='42501',message='Empleado fuera de la filial activa.';end if;
 if revision is distinct from md5(to_jsonb(e)::text)or employee_master_private.used(id)then raise exception using errcode='55000',message='El empleado cambió o tiene dependencias.';end if;delete from public.employees where employee_id=id;return true;end$$;
-- Reuse the four already protected public endpoints without widening master access.
alter function public.entity_master_list(text)set schema entity_master_private;
alter function public.entity_master_options(text)set schema entity_master_private;
alter function public.save_entity_master(text,jsonb,bigint)set schema entity_master_private;
alter function public.delete_entity_master(text,bigint,text)set schema entity_master_private;
create function public.entity_master_list(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='employees'then return employee_master_private.list();end if;return entity_master_private.entity_master_list(p_catalog);end$$;
create function public.entity_master_options(p_catalog text)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='employees'then return employee_master_private.options();end if;return entity_master_private.entity_master_options(p_catalog);end$$;
create function public.save_entity_master(p_catalog text,p_payload jsonb,p_id bigint default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='employees'then return employee_master_private.save(p_payload,p_id);end if;return entity_master_private.save_entity_master(p_catalog,p_payload,p_id);end$$;
create function public.delete_entity_master(p_catalog text,p_id bigint,p_revision text default null)returns boolean language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_catalog='employees'then return employee_master_private.remove(p_id,p_revision);end if;return entity_master_private.delete_entity_master(p_catalog,p_id,p_revision);end$$;
create or replace function public.entity_catalog_export_data(p_catalog text,p_search text default'')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform entity_master_private.identity();if p_catalog='employees'then perform employee_master_private.access('view');elsif p_catalog in('customers','suppliers')then perform entity_master_private.access(p_catalog,'view');end if;return entity_master_private.entity_catalog_export_data(p_catalog,p_search);end$$;
do $$declare p record;c record;begin for p in select policyname from pg_policies where schemaname='public'and tablename='employees'loop execute format('drop policy %I on public.employees',p.policyname);end loop;
 revoke all on public.employees from public,anon,authenticated,service_role;
 for c in select column_name from information_schema.columns where table_schema='public'and table_name='employees'loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.employees from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name);end loop;end$$;
alter table public.employees enable row level security;
create policy employee_master_read on public.employees for select to authenticated using(employee_master_private.visible(subsidiary_id));grant select on public.employees to authenticated;
revoke all on all functions in schema employee_master_private from public,anon,authenticated,service_role;
grant execute on function employee_master_private.visible(bigint)to authenticated;
revoke all on function entity_master_private.entity_master_list(text),entity_master_private.entity_master_options(text),entity_master_private.save_entity_master(text,jsonb,bigint),entity_master_private.delete_entity_master(text,bigint,text)from public,anon,authenticated,service_role;
revoke all on function public.entity_master_list(text),public.entity_master_options(text),public.save_entity_master(text,jsonb,bigint),public.delete_entity_master(text,bigint,text),public.entity_catalog_export_data(text,text)from public,anon,authenticated,service_role;
grant execute on function public.entity_master_list(text),public.entity_master_options(text),public.save_entity_master(text,jsonb,bigint),public.delete_entity_master(text,bigint,text),public.entity_catalog_export_data(text,text)to authenticated;
notify pgrst,'reload schema';
